tool_input.command:
$body = @{ model='workbuddy/deepseek-v4-pro'; messages=@(@{role='user';content='只输出JSON: {"allow":true}'}); max_tokens=256; temperature=0.2 } | ConvertTo-Json -Depth 5
try {
  $r = Invoke-RestMethod -Uri 'http://127.0.0.1:3425/v1/chat/completions' -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 60
  "OK content=" + $r.choices[0].message.content
  "usage=" + ($r.usage | ConvertTo-Json -Compress)
} catch { "ERR: $($_.Exception.Message)" }

$json = '{"model":"workbuddy/deepseek-v4-pro","messages":[{"role":"user","content":"只输出JSON: {\"allow\":true}"}],"max_tokens":256,"temperature":0.2}'
try {
  $r = Invoke-RestMethod -Uri 'http://127.0.0.1:3425/v1/chat/completions' -Method Post -Body $json -ContentType 'application/json' -TimeoutSec 60
  "OK content=" + $r.choices[0].message.content
  "usage=" + ($r.usage | ConvertTo-Json -Compress)
} catch { "ERR: $($_.Exception.Message)" }
